function storyline(format,spec,i){
 const concept=`TEST concept ${i+1}`;
 if(format==='video')return {kind:'video',concept,shots:[{visual:`TEST opening shot ${i+1}`,camera:'Slow push in',on_screen_text:''},{visual:`TEST closing shot ${i+1}`,camera:'Static',on_screen_text:'Learn more'}]};
 if(format==='carousel')return {kind:'carousel',concept,slides:Array.from({length:spec?.slide_count??3},(_,n,all)=>({role:n===0?'hook':n===(spec?.slide_count??3)-1?'cta':'point',message:`TEST slide ${n+1} of post ${i+1}`}))};
 if(spec?.placement==='story')return {kind:'story',concept,frames:[{visual:`TEST frame for post ${i+1}`,text:'Tap to learn more'}]};
 return {kind:'static',concept,hook:`TEST visual hook ${i+1}`,layout_archetype:['lifestyle_hero','product_hero','type_led_poster','comparison','offer','quote'][i%6],art_direction:'TEST soft daylight, product left, generous margin',on_image_copy:{headline:`TEST headline ${i+1}`,supporting:'',cta:'Learn more'}};
}
export function generatedPlan(input){const mix=input.content_mix?.flatMap(row=>Array.from({length:row.count},()=>row));return {title:'TEST FIXTURE: Thirty-day plan',strategy:'TEST FIXTURE: Mix practical tips and product explanations for the approved audience. Draft dates require review.',warnings:['TEST FIXTURE: No performance evidence supplied.'],slots:Array.from({length:input.post_count},(_,i)=>({channel:mix?.[i]?.channel??input.preferences.channels[i%input.preferences.channels.length],planned_at:new Date(Date.parse(input.preferences.starts_on)+Math.floor(i*(input.duration_days??30)/input.post_count)*86400000+8*3600000).toISOString(),format:mix?.[i]?.format??(i<(input.video_count??0)?'video':'static'),...(mix?{creative_spec:mix[i].creative_spec}:{}),...((mix?mix[i].format==='video':i<(input.video_count??0))?{video_draft:{storyline:`TEST video story ${i+1}`,script:`TEST script ${i+1}`,prompt:`TEST motion prompt ${i+1}`,duration_seconds:5}}:{}),...(input.strategy?{strategy_ref:(a=>({persona_id:a.persona_id,pain_id:a.pain_id,angle_id:a.id}))(input.strategy.angles[i%input.strategy.angles.length])}:{}),...(input.storylines?{storyline:storyline(mix?.[i]?.format??(i<(input.video_count??0)?'video':'static'),mix?.[i]?.creative_spec,i)}:{}),brief:`TEST FIXTURE: ${i+1}. Explain ${input.brand.facts.find(f=>f.field==='offering')?.value??'the approved offering'} with a distinct practical angle.`,pillar:i%2?'Education':'Product',hook:`TEST FIXTURE hook ${i+1}`,cta:'Learn more',fact_ids:[input.brand.facts.find(f=>f.field==='offering')?.id??input.brand.facts[0].id]}))};}
export function modelResponse(value){return Response.json({object:'response',id:'resp_plan_fixture',status:'completed',output:[{type:'message',content:[{type:'output_text',text:JSON.stringify(value),annotations:[]}]}],usage:{input_tokens:100,output_tokens:100,total_tokens:200}});}
